events.command:
/bin/bash -lc "perl -e '
"'$/="'"\\n>\";
my "'$q="CACACACAGGAGAT";
my $rc=reverse $q; $rc =~ tr/ACGT/TGCA/;
while (<>) {
  s/''^>//;
  my ($h,@lines)=split /'"\\n/;
  my ("'$id)=split /'"\\s+/, "'$h;
  my $s=uc(join("",@lines));
  for my $pair (["+",$q],["-",$rc]) {
    my ($strand,$needle)=@$pair;
    my $off=0;
    while (($off=index($s,$needle,$off)) >= 0) {
      print "$id'"\\t"'$off'"\\t\",("'$off+length($needle)),"'"\\t"'$strand'"\\t\",substr("'$s,$off,length($needle)),"'"\\n\";
      "'$off++;
    }
  }
}
'"' GCF_000001215.4_Release_6_plus_ISO1_MT_genomic.fna"

/bin/bash -lc "perl -e '
"'$/="'"\\n>\";
while (<>) {
  s/"'^>//;
  my ($h,@lines)=split /'"\\n/;
  my ("'$id)=split /'"\\s+/, "'$h;
  next unless $id eq "NT_033779.5";
  my $s=uc(join("",@lines));
  my $start=4280595; my $end=4280609;
  print "id=$id length=",length($s)," start=$start end=$end span=",($end-$start)," hit=",substr($s,$start,$end-$start)," context=",substr($s,$start-10,$end-$start+20),"'"\\n\";
}
' GCF_000001215.4_Release_6_plus_ISO1_MT_genomic.fna"
